    jsonb_build_object('number',13,'question',E'다음 빈칸 (A), (B), (C)에 들어갈 말로 가장 적절한 것은?\n• She had to stay home (A)___ her fever.\n• I was nervous (B)___ it was my first time speaking in public.\n• The road was closed (C)___ the heavy snowfall.\n       (A)           (B)          (C)','type','mcq','options',jsonb_build_array(E'because — because — because',E'because — because — because of',E'because of — because — because of',E'because of — because of — because',E'because — because of — because of'),'answer',E'3'),
    jsonb_build_object('number',14,'question',E'다음 두 문장을 의미에 맞는 접속사를 사용하여 한 문장으로 바르게 연결한 것은?\n• Animals are disappearing from the forest.\n• Humans are destroying their habitat.','type','mcq','options',jsonb_build_array(E'Animals are disappearing from the forest so humans are destroying their habitat.',E'Animals are disappearing from the forest and humans are destroying their habitat.',E'Animals are disappearing from the forest but humans are destroying their habitat.',E'Animals are disappearing from the forest because humans are destroying their habitat.',E'Animals are disappearing from the forest or humans are destroying their habitat.'),'answer',E'4'),
    jsonb_build_object('number',15,'question',E'다음 <보기>에 주어진 우리말을 바르게 영작한 것은?\n<보기> 눈이 많이 왔기 때문에 학교가 일찍 끝났다.','type','mcq','options',jsonb_build_array(E'School ends early because it snows a lot.',E'Because it snowed a lot, school ended early.',E'Because it snowed a lot, school ends early.',E'School ended early because it snows a lot.',E'Because school ended early, it snowed a lot.'),'answer',E'2'),
