    jsonb_build_object('number',27,'question',E'다음 밑줄 친 부분 중 어법상 올바른 것은?\n① I couldn''t focus <u>because</u> the construction noise outside.\n② She was happy <u>because</u> she finally got the job she wanted.\n③ He was upset <u>because of</u> his sister borrowed his laptop without asking.\n④ They were late <u>because of</u> they missed the last train.\n⑤ We canceled the trip <u>because</u> the bad forecast.','type','mcq','options',jsonb_build_array(E'I couldn''t focus because the construction noise outside.',E'She was happy because she finally got the job she wanted.',E'He was upset because of his sister borrowed his laptop without asking.',E'They were late because of they missed the last train.',E'We canceled the trip because the bad forecast.'),'answer',E'2'),
