    jsonb_build_object('number',41,'question',E'다음 빈칸에 공통으로 들어갈 말로 알맞은 것은?\n• She skipped the school trip ___ she had a high fever that morning.\n• The café was packed ___ a famous food blogger had recommended it.\n• He apologized immediately ___ he realized he had been rude.','type','mcq','options',jsonb_build_array(E'because of',E'so',E'because',E'but',E'and'),'answer',E'3'),
    jsonb_build_object('number',42,'question',E'다음 빈칸에 들어갈 알맞은 말을 바르게 짝지은 것은?\n• The power went out. ⓐ___ we had to use candles all night.\n• We had to use candles all night ⓑ___ the power went out.\n       ⓐ          ⓑ','type','mcq','options',jsonb_build_array(E'Because — so',E'But — and',E'So — because',E'That — because',E'When — so'),'answer',E'3'),
    jsonb_build_object('number',43,'question',E'다음 빈칸에 들어갈 말이 순서대로 짝지어진 것은?\n• He put on a coat ___ the temperature had dropped overnight.\n• She canceled her reservation ___ a sudden schedule change.','type','mcq','options',jsonb_build_array(E'for — because',E'because — because',E'because of — for',E'because — because of',E'because of — because'),'answer',E'4'),
    jsonb_build_object('number',44,'question',E'다음 빈칸에 들어갈 말로 알맞은 것은?\nJisoo looks really pleased because she ___.','type','mcq','options',jsonb_build_array(E'lost her favorite earrings',E'failed her math test again',E'got rejected from her first-choice university',E'received a full scholarship',E'missed the last bus home'),'answer',E'4'),
    jsonb_build_object('number',45,'question',E'다음 중 빈칸에 들어갈 말이 나머지 넷과 다른 것은?\n① She cried all night ___ she had a terrible fight with her best friend.\n② He studied abroad for a year, ___ his English improved significantly.\n③ I had to apologize ___ I forgot our appointment.\n④ We left early ___ the last train was at ten.\n⑤ She turned off her phone ___ she needed to concentrate on her essay.','type','mcq','options',jsonb_build_array(E'She cried all night ___ she had a terrible fight with her best friend.',E'He studied abroad for a year, ___ his English improved significantly.',E'I had to apologize ___ I forgot our appointment.',E'We left early ___ the last train was at ten.',E'She turned off her phone ___ she needed to concentrate on her essay.'),'answer',E'2'),
    jsonb_build_object('number',46,'question',E'다음 빈칸 (A), (B), (C)에 들어갈 말로 가장 적절한 것은?\n• He couldn''t join the hike (A)___ his sprained knee.\n• She stayed in the library all weekend (B)___ she had three reports due on Monday.\n• The bridge was shut down (C)___ the structural damage.\n       (A)           (B)          (C)','type','mcq','options',jsonb_build_array(E'because — because — because',E'because — because of — because',E'because of — because — because of',E'because of — because of — because',E'because — because — because of'),'answer',E'3'),
    jsonb_build_object('number',47,'question',E'다음 두 문장을 의미에 맞는 접속사를 사용하여 한 문장으로 바르게 연결한 것은?\n• Many young people are moving to big cities.\n• There are more job opportunities there.','type','mcq','options',jsonb_build_array(E'Many young people are moving to big cities so there are more job opportunities there.',E'Many young people are moving to big cities and there are more job opportunities there.',E'Many young people are moving to big cities but there are more job opportunities there.',E'Many young people are moving to big cities because there are more job opportunities there.',E'Many young people are moving to big cities or there are more job opportunities there.'),'answer',E'4'),
    jsonb_build_object('number',48,'question',E'다음 <보기>에 주어진 우리말을 바르게 영작한 것은?\n<보기> 그는 지갑을 잃어버렸기 때문에 집까지 걸어가야 했다.','type','mcq','options',jsonb_build_array(E'He walks home because he loses his wallet.',E'Because he lost his wallet, he had to walk home.',E'Because he lost his wallet, he has to walk home.',E'He had to walk home because he loses his wallet.',E'Because he had to walk home, he lost his wallet.'),'answer',E'2'),
    jsonb_build_object('number',49,'question',E'다음 빈칸에 공통으로 들어갈 단어가 아닌 것은?\n① He switched seats ___ the person next to him was talking loudly.\n② She started exercising every morning ___ she wanted to feel more energetic.\n③ I had to rewrite the essay ___ the teacher said it was off-topic.\n④ She is taller ___ her older sister.\n⑤ They arrived late ___ the traffic was worse than expected.','type','mcq','options',jsonb_build_array(E'He switched seats ___ the person next to him was talking loudly.',E'She started exercising every morning ___ she wanted to feel more energetic.',E'I had to rewrite the essay ___ the teacher said it was off-topic.',E'She is taller ___ her older sister.',E'They arrived late ___ the traffic was worse than expected.'),'answer',E'4'),
    jsonb_build_object('number',50,'question',E'다음 중 주어진 문장의 빈칸에 들어갈 말과 같은 것을 모두 고르면?\nHe put on extra blankets ___ the heating system broke down.\n① She couldn''t walk properly ___ her blisters.\n② I stayed after class ___ I had questions about the homework.\n③ The museum was interesting, ___ it was very crowded.\n④ She dropped her phone ___ she was startled by a loud noise.\n⑤ He forgot his lines on stage ___ he was too nervous.','type','mcq','options',jsonb_build_array(E'She couldn''t walk properly ___ her blisters.',E'I stayed after class ___ I had questions about the homework.',E'The museum was interesting, ___ it was very crowded.',E'She dropped her phone ___ she was startled by a loud noise.',E'He forgot his lines on stage ___ he was too nervous.'),'answer',E'2, 4, 5'),
    jsonb_build_object('number',51,'question',E'다음 중 빈칸에 들어갈 말이 나머지와 다른 것은?\n① She drank three glasses of water ___ she was very thirsty after the run.\n② He wore a helmet ___ cycling on that road can be dangerous.\n③ I love this café ___ I can''t stand the parking situation here.\n④ We had to postpone the match ___ one of our key players was injured.\n⑤ She took vitamin C every day ___ she didn''t want to get sick.','type','mcq','options',jsonb_build_array(E'She drank three glasses of water ___ she was very thirsty after the run.',E'He wore a helmet ___ cycling on that road can be dangerous.',E'I love this café ___ I can''t stand the parking situation here.',E'We had to postpone the match ___ one of our key players was injured.',E'She took vitamin C every day ___ she didn''t want to get sick.'),'answer',E'3'),
    jsonb_build_object('number',52,'question',E'다음 중 흐름상 어색한 문장은?\n① He wore a raincoat because it was pouring outside.\n② She felt relieved because the surgery went well.\n③ I opened the window because it was stuffy in the room.\n④ He was disappointed because he scored the highest in class.\n⑤ They moved to a smaller apartment because they wanted to save money.','type','mcq','options',jsonb_build_array(E'He wore a raincoat because it was pouring outside.',E'She felt relieved because the surgery went well.',E'I opened the window because it was stuffy in the room.',E'He was disappointed because he scored the highest in class.',E'They moved to a smaller apartment because they wanted to save money.'),'answer',E'4'),
    jsonb_build_object('number',53,'question',E'다음 중 원인과 결과의 관계가 어색한 문장은?\n① He bought a new umbrella because his old one broke.\n② She felt cold because she left her jacket at home.\n③ I went to the dentist because I had a toothache.\n④ Because she was full, she ordered three more dishes.\n⑤ Because the store was having a sale, I bought two pairs of shoes.','type','mcq','options',jsonb_build_array(E'He bought a new umbrella because his old one broke.',E'She felt cold because she left her jacket at home.',E'I went to the dentist because I had a toothache.',E'Because she was full, she ordered three more dishes.',E'Because the store was having a sale, I bought two pairs of shoes.'),'answer',E'4'),
    jsonb_build_object('number',54,'question',E'Choose one grammatically incorrect sentence.\n① He couldn''t finish the project because his laptop crashed.\n② She was happy because of her team''s victory.\n③ They canceled the picnic <u>because of it started to rain</u>.\n④ I bought flowers because I wanted to cheer her up.\n⑤ We stayed at the hotel an extra night because of the typhoon.','type','mcq','options',jsonb_build_array(E'He couldn''t finish the project because his laptop crashed.',E'She was happy because of her team''s victory.',E'They canceled the picnic because of it started to rain.',E'I bought flowers because I wanted to cheer her up.',E'We stayed at the hotel an extra night because of the typhoon.'),'answer',E'3'),
    jsonb_build_object('number',55,'question',E'다음 중 밑줄 친 부분의 쓰임이 잘못된 것은?\n① She gained confidence <u>because of</u> her coach''s encouragement.\n② He wore a cast <u>because of</u> he broke his wrist during practice.\n③ I took the stairs <u>because</u> the elevator was out of order.\n④ We had to reschedule <u>because of</u> the unexpected power outage.\n⑤ She smiled <u>because</u> she finally understood the problem.','type','mcq','options',jsonb_build_array(E'She gained confidence because of her coach''s encouragement.',E'He wore a cast because of he broke his wrist during practice.',E'I took the stairs because the elevator was out of order.',E'We had to reschedule because of the unexpected power outage.',E'She smiled because she finally understood the problem.'),'answer',E'2'),
    jsonb_build_object('number',56,'question',E'다음 중 밑줄 친 부분이 어법상 어색한 것은?\n① The café closed early <u>because of</u> staff shortage.\n② I had to repeat the year <u>because of</u> poor attendance.\n③ He was disqualified <u>because of</u> he used a banned substance.\n④ She took a long walk <u>because</u> she needed to clear her head.\n⑤ We couldn''t board the plane <u>because</u> we arrived after the gate closed.','type','mcq','options',jsonb_build_array(E'The café closed early because of staff shortage.',E'I had to repeat the year because of poor attendance.',E'He was disqualified because of he used a banned substance.',E'She took a long walk because she needed to clear her head.',E'We couldn''t board the plane because we arrived after the gate closed.'),'answer',E'3'),
    jsonb_build_object('number',57,'question',E'다음 빈칸에 ''because''를 쓸 수 있는 문장을 모두 고르면? (정답 2개)\n① He wore sunglasses ___ the bright glare.\n② I had to whisper ___ the baby was sleeping.\n③ She got a refund ___ a defect in the product.\n④ We went inside ___ the rain got heavier.\n⑤ They were late ___ a traffic accident on the highway.','type','mcq','options',jsonb_build_array(E'He wore sunglasses ___ the bright glare.',E'I had to whisper ___ the baby was sleeping.',E'She got a refund ___ a defect in the product.',E'We went inside ___ the rain got heavier.',E'They were late ___ a traffic accident on the highway.'),'answer',E'2, 4'),
    jsonb_build_object('number',58,'question',E'다음 중 어법상 어색한 것은?\n① She was shaking because of fear.\n② He stayed home because of the blizzard.\n③ I left early <u>because of tired</u>.\n④ We canceled because of the forecast.\n⑤ She was absent because of a family event.','type','mcq','options',jsonb_build_array(E'She was shaking because of fear.',E'He stayed home because of the blizzard.',E'I left early because of tired.',E'We canceled because of the forecast.',E'She was absent because of a family event.'),'answer',E'3'),
    jsonb_build_object('number',59,'question',E'다음 중 어법상 옳은 문장을 고르면?\n① She was absent because of her grandmother passed away.\n② He quit the club because of he lost interest.\n③ They postponed the launch because the product had a critical bug.\n④ I was nervous because the stage fright.\n⑤ We left early because the heavy traffic.','type','mcq','options',jsonb_build_array(E'She was absent because of her grandmother passed away.',E'He quit the club because of he lost interest.',E'They postponed the launch because the product had a critical bug.',E'I was nervous because the stage fright.',E'We left early because the heavy traffic.'),'answer',E'3'),
    jsonb_build_object('number',60,'question',E'다음 밑줄 친 부분 중 어법상 올바른 것은?\n① She had to rest <u>because</u> her exhaustion after the marathon.\n② He was embarrassed <u>because of</u> he tripped in front of everyone.\n③ I missed the ferry <u>because of</u> I overslept that morning.\n④ She wore earplugs <u>because</u> she couldn''t stand the noise.\n⑤ We stayed indoors <u>because of</u> it was dangerously icy outside.','type','mcq','options',jsonb_build_array(E'She had to rest because her exhaustion after the marathon.',E'He was embarrassed because of he tripped in front of everyone.',E'I missed the ferry because of I overslept that morning.',E'She wore earplugs because she couldn''t stand the noise.',E'We stayed indoors because of it was dangerously icy outside.'),'answer',E'4'),
    jsonb_build_object('number',61,'question',E'다음 중 어법상 어색한 문장을 모두 고르면? (답 2개)\n① She had to leave the concert early because of a migraine.\n② <u>Because of he forgot his password</u>, he couldn''t log in.\n③ I chose the window seat because I love watching the view.\n④ He decided to walk because of the fresh air.\n⑤ <u>Because of she didn''t study</u>, she failed the quiz.','type','mcq','options',jsonb_build_array(E'She had to leave the concert early because of a migraine.',E'Because of he forgot his password, he couldn''t log in.',E'I chose the window seat because I love watching the view.',E'He decided to walk because of the fresh air.',E'Because of she didn''t study, she failed the quiz.'),'answer',E'2, 5'),
    jsonb_build_object('number',62,'question',E'Which sentence is incorrect?\n① He skipped lunch because he wasn''t hungry.\n② Because of the long queue, she decided to leave.\n③ I turned off the lights <u>because of I wanted to save electricity</u>.\n④ She brought a first-aid kit because she always prepares for emergencies.\n⑤ Because the deadline was moved up, they had to work through the weekend.','type','mcq','options',jsonb_build_array(E'He skipped lunch because he wasn''t hungry.',E'Because of the long queue, she decided to leave.',E'I turned off the lights because of I wanted to save electricity.',E'She brought a first-aid kit because she always prepares for emergencies.',E'Because the deadline was moved up, they had to work through the weekend.'),'answer',E'3'),
    jsonb_build_object('number',63,'question',E'다음 중 빈칸에 들어갈 말로 알맞지 않은 것은? (단, 순서는 상관없음)\n• He was grinning. Because ___.\n• She stormed out of the room. Because ___.\n• They sat in silence. Because ___.\n• I ran to the gate. Because ___.','type','mcq','options',jsonb_build_array(E'he just got the news he was accepted',E'the argument had left everyone speechless',E'my boarding pass was already checked in online',E'someone had insulted her in front of the class',E'my flight was about to close'),'answer',E'3'),
    jsonb_build_object('number',64,'question',E'다음은 Junho의 이유나 원인을 나타내는 영어문장 만들기 숙제이다. 내용의 흐름이 자연스러운 문장의 개수를 고르면?\n• He wore a scarf because it was cold and windy outside.\n• She felt lonely because all her friends came to visit.\n• He stayed up all night because he had a deadline to meet.\n• I avoided the cafeteria because the food is always delicious.\n• She took a painkiller because she had a splitting headache.','type','mcq','options',jsonb_build_array(E'1개',E'2개',E'3개',E'4개',E'5개'),'answer',E'3'),
    jsonb_build_object('number',65,'question',E'다음 두 문장의 연결이 의미상 어색한 것은?\n① She brought an extra pen. She was afraid hers might run out.\n   → She brought an extra pen because she was afraid hers might run out.\n② He booked the earliest flight. He wanted to arrive before noon.\n   → He booked the earliest flight because he wanted to arrive before noon.\n③ I bought a new umbrella. I already had three umbrellas at home.\n   → I bought a new umbrella because I already had three umbrellas at home.\n④ She turned down the air conditioner. It was making her shiver.\n   → She turned down the air conditioner because it was making her shiver.\n⑤ He wore a warm hat. The forecast said temperatures would drop below zero.\n   → He wore a warm hat because the forecast said temperatures would drop below zero.','type','mcq','options',jsonb_build_array(E'She brought an extra pen because she was afraid hers might run out.',E'He booked the earliest flight because he wanted to arrive before noon.',E'I bought a new umbrella because I already had three umbrellas at home.',E'She turned down the air conditioner because it was making her shiver.',E'He wore a warm hat because the forecast said temperatures would drop below zero.'),'answer',E'3'),
    jsonb_build_object('number',66,'question',E'다음 짝지어진 대화 중 어색한 것은?\n① A: Why did you take the bus instead of the subway?\n   B: Because the subway line was under maintenance today.\n② A: Why is the classroom so quiet?\n   B: Because everyone is preparing for the speaking test.\n③ A: Why did Soyeon skip the team dinner?\n   B: Because she had to pick up her younger brother from school.\n④ A: Why didn''t you finish the report?\n   B: I have no idea. That''s because I ran out of ideas halfway through.\n⑤ A: Why is Minjun so tired today?\n   B: I have no idea. Why don''t you ask him yourself?','type','mcq','options',jsonb_build_array(E'A: Why did you take the bus instead of the subway? B: Because the subway line was under maintenance today.',E'A: Why is the classroom so quiet? B: Because everyone is preparing for the speaking test.',E'A: Why did Soyeon skip the team dinner? B: Because she had to pick up her younger brother from school.',E'A: Why didn''t you finish the report? B: I have no idea. That''s because I ran out of ideas halfway through.',E'A: Why is Minjun so tired today? B: I have no idea. Why don''t you ask him yourself?'),'answer',E'4')  );

